const retailFromMarkup=(costValue,markupValue)=>Number(costValue||0)*(1+Number(markupValue||0)/100);
const normalizedName=value=>String(value||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").trim().toLocaleUpperCase("el-GR").replace(/\s+/g," ");
